UPDATE tags
name = #{name}, code = #{code}, type = #{type}, color = #{color}, sort_order = #{sortOrder}, status = #{status}, update_time = #{updateTime}, updated_by = #{updatedBy},
WHERE id = #{id} AND shop_id = #{shopId}

UPDATE products SET tag_id = #{tagId}, update_time = #{now}
WHERE id IN

    #{pid}

AND shop_id = #{shopId}

UPDATE products SET tag_id = NULL, update_time = #{now}
WHERE tag_id = #{tagId} AND id IN

    #{pid}

AND shop_id = #{shopId}

UPDATE tags t
SET product_count = (SELECT COUNT(*) FROM products p WHERE p.tag_id = t.id AND p.shop_id = t.shop_id)
WHERE t.shop_id = #{shopId}
